import re


def parse_duration(s: str) -> float:
    number = r"([0-9]+(?:[.,][0-9]+)?)"
    pattern = (
        rf"P(?:{number}Y)?(?:{number}M)?(?:{number}W)?(?:{number}D)?"
        rf"(?:T(?:{number}H)?(?:{number}M)?(?:{number}S)?)?"
    )
    match = re.fullmatch(pattern, s)
    if match is None:
        raise ValueError("Invalid duration")

    components = match.groups()
    present = [value for value in components if value is not None]

    if not present:
        raise ValueError("Duration must contain at least one component")
    if "T" in s and not any(value is not None for value in components[4:]):
        raise ValueError("T must be followed by a time component")
    if any("." in value or "," in value for value in present[:-1]):
        raise ValueError("Only the last component may have a fractional part")

    factors = (365 * 86400, 30 * 86400, 7 * 86400, 86400, 3600, 60, 1)
    return sum(
        (
            float(value.replace(",", ".")) * factor
            for value, factor in zip(components, factors)
            if value is not None
        ),
        0.0,
    )
