def _numeric_key(value: str) -> tuple[int, str]:
    # Compare arbitrary-length numbers without Python's int-conversion limit.
    value = value.lstrip("0") or "0"
    return len(value), value


def _version_key(
    core: tuple[str, str, str], prerelease: str | None = None
) -> tuple:
    core_key = tuple(_numeric_key(part) for part in core)
    if prerelease is None:
        return core_key + (1, ())

    prerelease_key = tuple(
        (0, _numeric_key(part)) if part.isdigit() else (1, part)
        for part in prerelease.split(".")
    )
    return core_key + (0, prerelease_key)


def _parse_version(value: str) -> tuple[tuple[str, str, str], tuple]:
    match = _VERSION_RE.fullmatch(value)
    if match is None:
        raise ValueError(f"Malformed version: {value!r}")

    core = match.group(1, 2, 3)
    return core, _version_key(core, match.group(4))


def _increment(value: str) -> str:
    digits = list(value)
    index = len(digits) - 1

    while index >= 0 and digits[index] == "9":
        digits[index] = "0"
        index -= 1

    if index < 0:
        return "1" + "".join(digits)

    digits[index] = chr(ord(digits[index]) + 1)
    return "".join(digits)


def satisfies(version: str, range_expr: str) -> bool:
    _, version_key = _parse_version(version)
    range_matches = False

    # Validate every comparator, even after the result is already determined.
    for comparator_set in range_expr.split("||"):
        comparators = comparator_set.split()
        if not comparators:
            raise ValueError("The range and every comparator set must be nonempty")

        set_matches = True
        for comparator in comparators:
            if comparator == "*":
                continue

            match = _COMPARATOR_RE.fullmatch(comparator)
            if match is None:
                raise ValueError(f"Malformed comparator: {comparator!r}")

