                comparator_matches = version_key == target_key
            elif operator == ">":
                comparator_matches = version_key > target_key
            elif operator == ">=":
                comparator_matches = version_key >= target_key
            elif operator == "<":
                comparator_matches = version_key < target_key
            elif operator == "<=":
                comparator_matches = version_key <= target_key
